mapper.select:
SELECT t.* FROM memory_turns t
WHERE t.deleted = 0 AND t.gen_done = true
  AND t.user_id = #{userId}
  AND t.direction = #{direction}
  AND t.created_at >= NOW() - make_interval(days => #{relativeDays})
  AND t.created_at >= #{twStart}
  AND t.created_at <= #{twEnd}
ORDER BY t.created_at DESC

SELECT t.* FROM memory_turns t
WHERE t.deleted = 0 AND t.gen_done = true
  AND t.user_id = #{userId}
  AND t.tag_ids &&

          #{tid}

  AND t.direction = #{direction}
  AND t.created_at >= NOW() - make_interval(days => #{relativeDays})
  AND t.created_at >= #{twStart}
  AND t.created_at <= #{twEnd}
ORDER BY t.created_at ASC

SELECT t.* FROM memory_turns t WHERE t.deleted = 0
AND t.id IN #{tid}
AND 1 = 0 ORDER BY t.created_at ASC

SELECT t.* FROM memory_turns t
WHERE t.deleted = 0 AND t.gen_done = false AND t.user_id = #{userId}
ORDER BY t.created_at ASC
LIMIT #{limit}

mapper.update:
UPDATE memory_turns SET deleted = 1, updated_at = NOW() WHERE deleted = 0
AND id IN #{tid}
AND 1 = 0

mapper.select:
SELECT COUNT(*) FROM memory_turns t
WHERE t.deleted = 0 AND t.gen_done = true AND t.user_id = #{userId}
  AND NOT EXISTS (
      SELECT 1 FROM memory_summary_coverage c
      WHERE c.user_id = #{userId} AND c.turn_id = t.id
  )

SELECT t.* FROM memory_turns t
WHERE t.deleted = 0 AND t.user_id = #{userId}
  AND NOT (COALESCE(t.tag_ids, '{}'::bigint[]) @> ARRAY[#{tagId}]::bigint[])
  AND t.created_at < #{olderThanCreatedAt}
  AND t.created_at >= #{start}
  AND t.created_at <= #{end}
ORDER BY t.created_at ASC
LIMIT #{limit}
